 d={}
 if os.path.exists(ENV):
  for l in open(ENV,'r',encoding='utf-8',errors='ignore'):
   if '=' in l and not l.strip().startswith('#'):
    try: k,v=l.strip().split('=',1); d[k.strip()]=v.strip()
    except: pass
 return d
def save_env(d):
 os.makedirs(os.path.dirname(ENV), exist_ok=True)
 open(ENV,'w',encoding='utf-8').write(''.join([f"{k}={v}\n" for k,v in d.items()]))
